<!doctype html>
<html lang="en"><?php include '../include/page-config.php'; require_once '../data/demo-data.php'; include '../include/head.php'; ?>
<style>.demo-label{font-size:.75rem;color:var(--bs-secondary-color)}.barcode-card{border:1px dashed #adb5bd;border-radius:.35rem;padding:.65rem;text-align:center;background:#fff;color:#111}.barcode-card svg{max-width:100%;height:54px}@media print{body *{visibility:hidden!important}#print-area,#print-area *{visibility:visible!important}#print-area{position:absolute;left:0;top:0;width:100%;display:grid!important;grid-template-columns:repeat(3,1fr);gap:5mm;padding:5mm}.no-print{display:none!important}}</style>
<body class="layout-fixed sidebar-expand-lg bg-body-tertiary"><div class="app-wrapper"><?php include '../layout/header.php'; include '../layout/sidebar.php'; ?><main class="app-main"><?php include '../layout/page-header.php'; ?><div class="app-content"><div class="container-fluid"><div class="card"><div class="card-header"><h3 class="card-title">New purchase</h3></div><div class="card-body"><div class="alert alert-info">Demo UI only. Saving a purchase does not change stock or supplier balances.</div><div class="row g-3"><div class="col-md-4"><label class="form-label">Supplier</label><select class="form-select"><?php foreach($demoSuppliers as $s): ?><option><?= htmlspecialchars($s['supplier_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Purchase date</label><input class="form-control" type="date" value="2026-11-14"></div><div class="col-md-4"><label class="form-label">Reference</label><input class="form-control" value="PUR-DEMO-00016"></div></div><hr><div class="row g-2 align-items-end"><div class="col-md-6"><label class="form-label">Product</label><select id="purchase-product" class="form-select"><?php foreach($demoProducts as $p): ?><option value="<?= (int)$p['id'] ?>"><?= htmlspecialchars($p['product'].' · '.$p['sku']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Quantity</label><input id="purchase-qty" class="form-control" type="number" min="1" value="12"></div><div class="col-md-2"><label class="form-label">Unit cost</label><input id="purchase-cost" class="form-control" type="number" min="0" value="62"></div><div class="col-md-2"><button id="purchase-add" class="btn btn-outline-primary w-100">Add item</button></div></div><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Unit cost</th><th class="text-end">Total</th></tr></thead><tbody id="purchase-lines"><tr><td colspan="4" class="text-center">No items added.</td></tr></tbody></table></div><div class="text-end fs-5">Total: <strong id="purchase-total">Rs. 0.00</strong></div></div><div class="card-footer"><button class="btn btn-primary" disabled>Save purchase (backend pending)</button></div></div><script>(()=>{const products=<?= json_encode($demoProducts,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;const lines=[];const money=n=>'Rs. '+n.toLocaleString('en-PK',{minimumFractionDigits:2});function draw(){document.getElementById('purchase-lines').innerHTML=lines.map(x=>'<tr><td>'+x.name+'</td><td>'+x.qty+'</td><td>'+money(x.cost)+'</td><td class="text-end">'+money(x.qty*x.cost)+'</td></tr>').join('')||'<tr><td colspan="4" class="text-center">No items added.</td></tr>';document.getElementById('purchase-total').textContent=money(lines.reduce((a,x)=>a+x.qty*x.cost,0));}document.getElementById('purchase-add').onclick=()=>{const p=products.find(x=>String(x.id)===document.getElementById('purchase-product').value);if(p)lines.push({name:p.product,qty:Math.max(1,+document.getElementById('purchase-qty').value||1),cost:Math.max(0,+document.getElementById('purchase-cost').value||0)});draw();};})();</script></div></div></main><?php include '../layout/footer.php'; ?></div><?php include '../include/footer-scripts.php'; ?></body></html>